import java.util.Scanner;

public class Main {
    static final int NN = 1000111;
    static final long mod = 1000000007L;
    static long[] vst = new long[NN];
    static long[] arr = new long[NN];

    static long power(long u, int n) {
        if (n == 0) return 1;
        long ans = power(u, n / 2);
        ans = ans * ans % mod;
        if ((n & 1) == 1) ans = ans * u % mod;
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(power(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(power(p, p));
            return;
        }

        int step = 0;
        for (int i = 1; i < p; i++) {
            if (vst[i] != 0) continue;
            long u = i, cnt = 0;
            while (vst[(int) u] == 0) {
                vst[(int) u] = 1;
                u = (u * k) % p;
                cnt++;
            }
            arr[(int) cnt]++;
        }

        long ans = 1;
        for (int i = 1; i <= p - 1; i++) {
            if (arr[i] == 0) continue;
            long tmp = power((i * arr[i] + 1) % mod, (int) arr[i]);
            ans = (ans * tmp) % mod;
        }

        System.out.println(ans);
        sc.close();
    }
}
